<?php
declare(strict_types=1);
require_once __DIR__.'/../standalone/bootstrap.php';
require_once __DIR__.'/../autoloader.php';
require_once __DIR__.'/../Repository/ConfigManagerRepository.php';
require_once __DIR__.'/../Service/ConfigManagerService.php';
require_once __DIR__.'/../Controller/ConfigManagerController.php';
require_once __DIR__.'/../lib/config_manager_runtime.php';
if (!mmbb_has_service('ConfigManager')) { http_response_code(403); echo 'Forbidden'; exit; }
use ConfigManager\Repository\ConfigManagerRepository;
use ConfigManager\Service\ConfigManagerService;
use ConfigManager\Controller\ConfigManagerController;
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
$csrf=(string)$_SESSION['csrf_token'];
function fw_json(array $x,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control:no-store');echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function fw_servers():array{return cm_load_config_manager_servers(__DIR__.'/../config/config.php');}
function fw_find(array $servers,string $name):array{foreach($servers as $s)if(strcasecmp((string)($s['name']??''),$name)===0)return $s;throw new RuntimeException('Unbekannter Server.',404);}
function fw_ctl(array $server):ConfigManagerController{return new ConfigManagerController(new ConfigManagerService(new ConfigManagerRepository($server)));}
function fw_body():array{$x=json_decode((string)file_get_contents('php://input'),true);if(!is_array($x))throw new InvalidArgumentException('Ungültiges JSON.');return $x;}
function fw_unwrap(array $r):array{$c=(int)($r['http_code']??500);$x=is_array($r['response']??null)?$r['response']:[];if($c<200||$c>=300||empty($x['ok']))throw new RuntimeException((string)($x['error']??('Agent HTTP '.$c)),$c>=400&&$c<=599?$c:502);return $x;}
try{
 $servers=fw_servers();
 if(($_GET['api']??'')==='summary')fw_json(['ok'=>true,'servers'=>array_map(fn($s)=>['name'=>(string)($s['name']??'')],$servers)]);
 if(($_GET['api']??'')==='load'){$srv=fw_find($servers,trim((string)($_GET['server']??'')));fw_json(['ok'=>true,'info'=>fw_unwrap(fw_ctl($srv)->getFirewallInfo())]);}
 if($_SERVER['REQUEST_METHOD']==='POST'){
   $in=fw_body();if(!hash_equals($csrf,(string)($in['csrf_token']??'')))throw new RuntimeException('CSRF fehlgeschlagen.',403);$srv=fw_find($servers,trim((string)($in['server_name']??'')));$ctl=fw_ctl($srv);$action=(string)($in['action']??'');
   if($action==='install'){$r=fw_unwrap($ctl->installFirewall());mmbb_audit_write('firewall_install',(string)$srv['name'],['server'=>(string)$srv['name']],'firewall.php','ok');fw_json(['ok'=>true,'result'=>$r]);}
   if($action==='change'){$change=['action'=>(string)($in['rule_action']??''),'kind'=>(string)($in['kind']??''),'zone'=>(string)($in['zone']??''),'value'=>(string)($in['value']??''),'confirm_lockout'=>!empty($in['confirm_lockout'])];$r=fw_unwrap($ctl->changeFirewallRule($change));mmbb_audit_write('firewall_rule',(string)$srv['name'],['server'=>(string)$srv['name']]+$change,'firewall.php','ok');fw_json(['ok'=>true,'result'=>$r]);}
   if($action==='zone'){$zn=(string)($in['zone']??'');$za=(string)($in['zone_action']??'');$r=fw_unwrap($ctl->administerFirewallZone($za,$zn));mmbb_audit_write('firewall_zone',(string)$srv['name'],['server'=>(string)$srv['name'],'action'=>$za,'zone'=>$zn],'firewall.php','ok');fw_json(['ok'=>true,'result'=>$r]);}
   if($action==='changes'){$changes=is_array($in['changes']??null)?$in['changes']:[];$confirm=!empty($in['confirm_lockout']);$r=fw_unwrap($ctl->changeFirewallRules($changes,$confirm));mmbb_audit_write('firewall_rules',(string)$srv['name'],['server'=>(string)$srv['name'],'count'=>count($changes),'changes'=>$changes],'firewall.php','ok');fw_json(['ok'=>true,'result'=>$r]);}
   if($action==='service'){$svcAction=(string)($in['service_action']??'');$r=fw_unwrap($ctl->controlFirewallService($svcAction));mmbb_audit_write('firewall_service',(string)$srv['name'],['server'=>(string)$srv['name'],'action'=>$svcAction],'firewall.php','ok');fw_json(['ok'=>true,'result'=>$r]);}
   throw new InvalidArgumentException('Unbekannte Aktion.');
 }
}catch(Throwable $e){$c=(int)$e->getCode();if($c<400||$c>599)$c=400;if(isset($_GET['api'])||$_SERVER['REQUEST_METHOD']==='POST')fw_json(['ok'=>false,'error'=>$e->getMessage()],$c);$pageError=$e->getMessage();}
?>
