rm-control" type="number" min="0" max="128" placeholder="24"></div><div class="col-sm-3"><label class="form-label fw-semibold">Port</label><input id="spPort" class="form-control" placeholder="443"></div><div class="col-sm-2"><label class="form-label fw-semibold">Protokoll</label><select id="spProto" class="form-select"><option value="tcp">TCP</option><option value="udp">UDP</option><option value="sctp">SCTP</option></select></div></div></div><div id="richFields" class="col-lg-8 d-none"><label class="form-label fw-semibold">Rich Rule</label><textarea id="richRule" class="form-control" rows="2" placeholder='rule family="ipv4" source address="10.0.0.0/8" service name="https" accept'></textarea></div><div class="col-lg-4"><div class="d-flex gap-2 justify-content-lg-end"><button id="stageRule" class="btn btn-outline-success"><i class="bi bi-bookmark-plus me-1"></i>Vormerken</button><button id="addRule" class="btn btn-success"><i class="bi bi-plus-lg me-1"></i>Anwenden</button></div></div></div><div class="mt-2"><div id="preview" class="fw-preview">—</div><div id="validation" class="small mt-1"></div></div></div></div>
