const CSRF=<?=json_encode($csrf)?>,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));let INFO=null,KIND='port',STAGE=[];function msg(t,k='info'){$('msg').innerHTML=`<div class="alert alert-${k}">${esc(t)}</div>`}let BUSY_TIMER=null;function busy(text='Firewall-Status wird geladen …'){const b=$('fwBusy');if(!b)return;$('fwBusyText').textContent=text;$('fwBusyHint').textContent='';b.classList.remove('d-none');clearTimeout(BUSY_TIMER);BUSY_TIMER=setTimeout(()=>{$('fwBusyHint').textContent='Die Abfrage dauert länger als erwartet. firewalld bzw. D-Bus antwortet noch.'},2000)}function idle(){clearTimeout(BUSY_TIMER);BUSY_TIMER=null;const b=$('fwBusy');if(b)b.classList.add('d-none')}async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',...opt});const j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.error||`HTTP ${r.status}`);return j}function ruleRow(zone,kind,value){const labels={port:'Port',service:'Service',source:'Quelle',source_port:'Port + Quelle',rich_rule:'Rich Rule',interface:'Interface'};return `<div class="fw-rule"><span class="badge text-bg-secondary">${esc(labels[kind]||kind)}</span><code>${esc(value)}</code><button class="btn btn-sm btn-outline-danger" title="Regel entfernen" data-remove data-zone="${esc(zone)}" data-kind="${esc(kind)}" data-value="${esc(value)}"><i class="bi bi-trash"></i></button></div>`}
function zoneOptions(){const keep=$('addZone').value;const def=INFO?.default_zone||'';const names=[...new Set((INFO?.zones||[]).map(x=>x.name).filter(Boolean))];$('addZone').innerHTML=names.map(x=>{const z=(INFO?.zones||[]).find(y=>y.name===x);const tag=x===def?' (Standard)':(z&&!z.active?' (inaktiv)':'');return `<option value="${esc(x)}">${esc(x)}${esc(tag)}</option>`}).join('');const pick=names.includes(keep)?keep:(names.includes(def)?def:names[0]||'');if(pick)$('addZone').value=pick}function render(){const z=INFO?.zones||[];$('installed').textContent=INFO?.installed?'Ja':'Nein';$('service').innerHTML=INFO?.service?.active?'<span class="text-success">aktiv</span>':(INFO?.installed?'<span class="text-warning">inaktiv</span>':'nicht installiert');$('backend').textContent=INFO?.backend||'none';$('zoneCount').textContent=`${z.filter(x=>x.active).length} / ${z.length}`;const inst=!!INFO?.installed,act=!!INFO?.service?.active;$('svcStart').disabled=!inst||act;$('svcRestart').disabled=!inst||!act;$('svcStop').disabled=!inst||!act;const available=INFO?.install?.available!==false;$('install').disabled=!!INFO?.installed||(!INFO?.installed&&!available);$('install').innerHTML=INFO?.installed?'<i class="bi bi-check-circle me-1"></i>firewalld installiert':(available?'<i class="bi bi-download me-1"></i>firewalld installieren':'<i class="bi bi-exclamation-triangle me-1"></i>Paket nicht verfügbar');$('install').title=(!INFO?.installed&&!available)?('Paketquelle liefert firewalld nicht: '+(INFO?.install?.error||'keine Version in den konfigurierten Repositories gefunden')):'';$('addRule').disabled=!INFO?.installed||INFO?.backend!=='firewalld';$('addRule').title=(INFO?.installed&&!INFO?.service?.active)?'firewalld wird vor der Aenderung gestartet; Agent-Port und SSH werden vorher freigegeben.':'';
const src=INFO?.config_source||(INFO?.service?.active?'runtime':((INFO?.zones||[]).length?'permanent':'unknown')),note=$('sourceNote');
if(src==='permanent'){note.classList.remove('d-none');note.innerHTML='<i class="bi bi-exclamation-triangle me-1"></i>firewalld ist gestoppt. Angezeigt wird die <strong>permanente</strong> Konfiguration, also der Stand, der nach einem Start gelten wuerde. Beim Start werden Agent-Port '+esc(INFO?.agent_port||'')+'/tcp und SSH automatisch freigegeben, damit dieser Host erreichbar bleibt.'}
else if(src==='none'&&INFO?.installed&&!INFO?.service?.active){note.classList.remove('d-none');note.innerHTML='<i class="bi bi-exclamation-triangle me-1"></i>firewalld ist gestoppt und die permanente Konfiguration ist nicht lesbar. <code>firewall-offline-cmd</code> fehlt auf diesem Host.'}
else note.classList.add('d-none');zoneOptions();renderSelectedZone();renderZones();document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>change('remove',b.dataset.kind,b.dataset.zone,b.dataset.value));updatePreview()}
const BUILTIN=['block','dmz','docker','drop','external','home','internal','nm-shared','public','trusted','work'];let ZONEFILTER='configured';
function zoneConfigured(x){return !!(x.default||x.active||(x.ports||[]).length||(x.services||[]).length||(x.sources||[]).length||(x.rich_rules||[]).length||(x.interfaces||[]).length)}
function cleanTarget(t){const v=String(t||'').replace(/%%/g,'').trim();return v&&v!=='default'?v:'default'}
function zoneNics(name){return (INFO?.interfaces||[]).filter(n=>n.zone===name)}
function freeOrOtherNics(name){return (INFO?.interfaces||[]).filter(n=>n.zone!==name)}
function selectedZone(){return (INFO?.zones||[]).find(x=>x.name===$('addZone').value)||null}
function compactChip(text,removeAttr=''){return `<span class="fw-interface-chip"><code>${esc(text)}</code>${removeAttr}</span>`}
function renderSelectedZone(){
 const x=selectedZone(); if(!x){$('selectedZoneState').innerHTML='';$('zoneInterfaces').textContent='—';$('zoneSources').textContent='—';$('selectedRules').innerHTML='<div class="fw-empty">Keine Zone ausgewählt.</div>';return}
 const assigned=zoneNics(x.name), builtin=BUILTIN.includes(x.name); const state=x.active?'<span class="badge text-bg-success">aktiv</span>':'<span class="badge text-bg-secondary">nicht aktiv</span>';
 $('selectedZoneState').innerHTML=`${state}${x.default?' <span class="badge text-bg-primary">Standard</span>':''}${builtin?' <span class="badge text-bg-light border text-dark">Systemzone</span>':''}<div class="fw-help mt-1">Target ${esc(cleanTarget(x.target))}${builtin?' · Systemzonen werden nicht gelöscht, sondern bei Nichtgebrauch ausgeblendet.':''}</div>`;
 $('zoneInterfaces').innerHTML=assigned.length?assigned.map(n=>compactChip(n.name,`<button class="btn btn-sm btn-link text-danger p-0" data-selected-nic-remove="${esc(n.name)}" title="Zuordnung entfernen"><i class="bi bi-x-circle"></i></button>`)).join(''):'<span class="text-body-secondary">keine</span>';
 const candidates=freeOrOtherNics(x.name); $('zoneNicPick').innerHTML='<option value="">Interface auswählen …</option>'+candidates.map(n=>`<option value="${esc(n.name)}">${esc(n.name)}${n.zone?' – aktuell '+esc(n.zone):''}</option>`).join(''); $('zoneNicAdd').disabled=!candidates.length;
 const sources=x.sources||[]; $('zoneSources').innerHTML=sources.length?sources.map(v=>compactChip(v,`<button class="btn btn-sm btn-link text-danger p-0" data-selected-source-remove="${esc(v)}" title="Netzzuordnung entfernen"><i class="bi bi-x-circle"></i></button>`)).join(''):'<span class="text-body-secondary">keine</span>';
 const rows=[];(x.services||[]).forEach(v=>rows.push(ruleRow(x.name,'service',v)));(x.ports||[]).forEach(v=>rows.push(ruleRow(x.name,'port',v)));(x.rich_rules||[]).forEach(v=>rows.push(ruleRow(x.name,'rich_rule',v)));
 $('selectedRuleCount').textContent=rows.length;$('selectedRules').innerHTML=rows.length?rows.join(''):'<div class="fw-empty">Noch keine Freigaben in dieser Zone.</div>';
 document.querySelectorAll('[data-selected-nic-remove]').forEach(b=>b.onclick=()=>removeNicFromZone(x.name,b.dataset.selectedNicRemove));
 document.querySelectorAll('[data-selected-source-remove]').forEach(b=>b.onclick=()=>change('remove','source',x.name,b.dataset.selectedSourceRemove));
 document.querySelectorAll('#selectedRules [data-remove]').forEach(b=>b.onclick=()=>change('remove',b.dataset.kind,b.dataset.zone,b.dataset.value));
}
function setZoneFilter(mode){ZONEFILTER=mode;['Configured','All'].forEach(n=>{const b=$('filter'+n);if(b)b.classList.toggle('active',mode===n.toLowerCase())});renderZones()}
function renderZones(){const all=INFO?.zones||[];let shown=ZONEFILTER==='all'?all:all.filter(zoneConfigured);
 if(!shown.length){$('zones').innerHTML='<div class="card"><div class="fw-empty">Keine verwendeten Zonen.</div></div>';return}
 $('zones').innerHTML=`<div class="card"><div class="table-responsive"><table class="table table-sm mb-0 fw-compact-table"><thead><tr><th>Zone</th><th>Status</th><th>Zuordnung</th><th>Freigaben</th><th></th></tr></thead><tbody>${shown.map(x=>{const nics=zoneNics(x.name).map(n=>n.name);const src=x.sources||[];const binds=[...nics,...src].join(', ')||'—';const rules=(x.ports||[]).length+(x.services||[]).length+(x.rich_rules||[]).length;const builtin=BUILTIN.includes(x.name);const del=builtin?'<span class="fw-system-note">Systemzone</span>':`<button class="btn btn-sm btn-outline-danger" data-zone-del="${esc(x.name)}" title="Eigene Zone löschen"><i class="bi bi-trash"></i></button>`;return `<tr class="${x.name===$('addZone').value?'table-active':''}"><td><button class="btn btn-link btn-sm p-0 fw-semibold" data-zone-open="${esc(x.name)}">${esc(x.name)}</button>${x.default?' <span class="badge text-bg-primary">Standard</span>':''}</td><td>${x.active?'<span class="text-success">aktiv</span>':'<span class="text-body-secondary">inaktiv</span>'}</td><td><code>${esc(binds)}</code></td><td>${rules}</td><td class="text-end">${del}</td></tr>`}).join('')}</tbody></table></div></div>`;
 document.querySelectorAll('[data-zone-open]').forEach(b=>b.onclick=()=>{$('addZone').value=b.dataset.zoneOpen;renderSelectedZone();renderZones();updatePreview();window.scrollTo({top:$('addZone').getBoundingClientRect().top+window.scrollY-100,behavior:'smooth'})});
 document.querySelectorAll('[data-zone-del]').forEach(b=>b.onclick=()=>zoneAdmin('delete',b.dataset.zoneDel));
}
async function assignNicToZone(zone){const sel=$('zoneNicPick'),nic=sel?.value||'';if(!nic)return;const cur=(INFO?.interfaces||[]).find(n=>n.name===nic);const from=cur?.zone||'keiner Zone';if(!confirm(`${nic} der Zone ${zone} zuordnen?\n\nAktuell: ${from}\nNeu: ${zone}\n\nDie Firewall-Regeln von ${zone} gelten danach für eingehenden Verkehr über ${nic}.`))return;busy(`Interface ${nic} wird ${zone} zugewiesen …`);try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'change',server_name:$('server').value,rule_action:'add',kind:'interface',zone,value:nic,confirm_lockout:true})});msg(`${nic} wurde ${zone} zugeordnet.`,'success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}}
async function removeNicFromZone(zone,nic){if(!confirm(`${nic} aus Zone ${zone} entfernen?\n\nWenn die Zone keine weitere Quelle oder Schnittstelle besitzt, wird sie danach inaktiv.`))return;busy(`Interface ${nic} wird aus ${zone} entfernt …`);try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'change',server_name:$('server').value,rule_action:'remove',kind:'interface',zone,value:nic,confirm_lockout:true})});msg(`${nic} wurde aus ${zone} entfernt.`,'success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}}
function setKind(k){KIND=k;document.querySelectorAll('.fw-type-btn').forEach(b=>b.classList.toggle('active',b.dataset.kind===k));['port','service','source_port','rich'].forEach(n=>$(n+'Fields').classList.toggle('d-none',!((k==='rich_rule'?'rich':k)===n)));updatePreview()}function validPort(v){if(/^\d+$/.test(v)){const n=+v;return n>=1&&n<=65535}const m=v.match(/^(\d+)-(\d+)$/);return !!m&&+m[1]>=1&&+m[2]<=65535&&+m[1]<=+m[2]}function isIPv4(ip){const p=ip.split('.');return p.length===4&&p.every(x=>/^\d+$/.test(x)&&+x>=0&&+x<=255)}function isIPv6(ip){return ip.includes(':')&&/^[0-9A-Fa-f:]+$/.test(ip)}function buildValue(){let value='',error='';if(KIND==='port'){const p=$('portNumber').value.trim(),proto=$('portProto').value;if(!validPort(p))error='Port muss 1–65535 oder ein gültiger Bereich wie 8000-8100 sein.';else value=p+'/'+proto}else if(KIND==='service'){const s=$('serviceName').value.trim();if(!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(s))error='Ungültiger Service-Name.';else value=s}else if(KIND==='source_port'){const ip=$('spIp').value.trim(),pre=$('spPrefix').value.trim(),port=$('spPort').value.trim(),proto=$('spProto').value,v4=isIPv4(ip),v6=isIPv6(ip);if(!v4&&!v6)error='Bitte eine gültige Quell-IP oder Netzadresse eingeben.';else if(!validPort(port))error='Port muss 1–65535 oder ein gültiger Bereich sein.';else{const max=v4?32:128,p=pre===''?(v4?32:128):+pre;if(!Number.isInteger(p)||p<0||p>max)error='Präfix muss zwischen 0 und '+max+' liegen.';else value=ip+'/'+p+'|'+port+'/'+proto}}else{value=$('richRule').value.trim();if(!/^rule\b/.test(value))error='Rich Rule muss mit "rule" beginnen.'}return{value,error}}
function existingValues(zone,kind){const z=(INFO?.zones||[]).find(x=>x.name===zone);if(!z)return[];if(kind==='port')return z.ports||[];if(kind==='service')return z.services||[];if(kind==='source')return z.sources||[];return z.rich_rules||[]}
function richFor(kind,value){if(kind!=='source_port')return value;const[src,pp]=String(value).split('|');const[port,proto]=String(pp||'').split('/');const fam=src.includes(':')?'ipv6':'ipv4';return `rule family="${fam}" source address="${src}" port port="${port}" protocol="${proto}" accept`}
function alreadySet(zone,kind,value){return existingValues(zone,kind).includes(richFor(kind,value))}
function stagedAlready(zone,kind,value){return STAGE.some(r=>r.zone===zone&&r.kind===kind&&r.value===value)}
function fieldsEmpty(){const v={port:['portNumber'],service:['serviceName'],source_port:['spIp','spPort'],rich_rule:['richRule']}[KIND]||[];return v.every(id=>!$(id).value.trim())}
function updatePreview(){const empty=fieldsEmpty();const {value,error}=empty?{value:'',error:''}:buildValue();$('preview').textContent=value||'—';const zone=$('addZone').value;let cls=error?'text-danger':'text-success',txt=error||(value?'Eingabe gültig.':'');
if(!error&&value&&alreadySet(zone,KIND,value)){cls='text-warning-emphasis';txt='Bereits in Zone '+zone+' gesetzt. Ein erneutes Anwenden aendert nichts.'}
else if(!error&&value&&stagedAlready(zone,KIND,value)){cls='text-warning-emphasis';txt='Steht bereits auf der Vormerkliste.'}
$('validation').className='small mt-2 '+cls;$('validation').textContent=empty?'':txt;
const ready=!!value&&!error;$('stageRule').disabled=!ready;$('addRule').disabled=!ready||!INFO?.installed||INFO?.backend!=='firewalld';
renderStage()}
async function load(label='Firewall-Status wird geladen …'){busy(label);const t0=performance.now();try{const j=await api('firewall.php?api=load&server='+encodeURIComponent($('server').value));INFO=j.info;render();const ms=Math.round(performance.now()-t0);msg(`Firewall-Status geladen (${ms} ms).`,'success')}catch(e){INFO=null;msg(e.message,'danger')}finally{idle()}}function lockoutRelevant(kind,value){const p=INFO?.agent_port?String(INFO.agent_port)+'/tcp':'';return kind==='interface'||(kind==='service'&&String(value).toLowerCase()==='ssh')||(kind==='port'&&p&&value===p)}
async function change(action,kind,zone,value){if(action==='remove'&&!confirm(`Regel wirklich entfernen?\n${value}`))return;let confirmLockout=false;
 if(action==='remove'&&lockoutRelevant(kind,value)){if(!confirm(`Achtung: ${value} betrifft den Verwaltungszugang zu diesem Host.\nNach dem Entfernen kann das Portal den Agenten moeglicherweise nicht mehr erreichen.\n\nTrotzdem entfernen?`))return;confirmLockout=true}
 busy(action==='add'?'Firewall-Regel wird angewendet …':'Firewall-Regel wird entfernt …');try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'change',server_name:$('server').value,rule_action:action,kind,zone,value,confirm_lockout:confirmLockout})});msg(action==='add'?'Regel hinzugefügt.':'Regel entfernt.','success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}}function renderStage(){const n=STAGE.length;$('stage').classList.toggle('d-none',n===0);$('stageCount').textContent=n;
const labels={port:'Port',service:'Service',source:'Quelle',source_port:'Port + Quelle',rich_rule:'Rich Rule'};
$('stageList').innerHTML=STAGE.map((r,i)=>{const dup=alreadySet(r.zone,r.kind,r.value);const tag=dup?' <span class="badge text-bg-warning text-dark">bereits gesetzt</span>':'';return `<div class="fw-rule"><span class="badge text-bg-secondary">${esc(labels[r.kind]||r.kind)}</span><span><code>${esc(r.zone)} · ${esc(r.value)}</code>${tag}</span><button class="btn btn-sm btn-outline-danger" data-stage-del="${i}"><i class="bi bi-x-lg"></i></button></div>`}).join('');
document.querySelectorAll('[data-stage-del]').forEach(b=>b.onclick=()=>{STAGE.splice(+b.dataset.stageDel,1);renderStage()})}
async function applyStage(){if(!STAGE.length)return;busy('Vorgemerkte Firewall-Regeln werden angewendet …');try{const j=await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'changes',server_name:$('server').value,changes:STAGE})});const res=j.result?.results||[];const neu=res.filter(r=>r.ok&&!r.already&&!r.missing).length,schon=res.filter(r=>r.already).length;STAGE=[];renderStage();msg(`${res.length} Regeln verarbeitet: ${neu} neu gesetzt, ${schon} waren bereits vorhanden.`,'success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}}
async function zoneAdmin(action,zone){if(action==='delete'&&!confirm(`Eigene Zone ${zone} wirklich loeschen?`))return;busy(action==='create'?'Zone wird angelegt …':'Zone wird gelöscht …');try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'zone',server_name:$('server').value,zone_action:action,zone})});msg(action==='create'?`Zone ${zone} angelegt.`:`Zone ${zone} geloescht.`,'success');await load();if(action==='create'&&[...$('addZone').options].some(o=>o.value===zone)){$('addZone').value=zone;renderSelectedZone();renderZones()}}catch(e){msg(e.message,'danger');idle()}}
async function svc(action){const labels={enable:'starten',restart:'neu starten',disable:'stoppen'};if(action==='disable'&&!confirm('firewalld auf diesem Server wirklich stoppen und deaktivieren?\nDer Host ist danach ohne Paketfilter erreichbar.'))return;busy('firewalld wird '+labels[action]+' …');try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'service',server_name:$('server').value,service_action:action})});msg('firewalld '+labels[action]+': erfolgreich.','success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}}
async function init(){const j=await api('firewall.php?api=summary');$('server').innerHTML=(j.servers||[]).map(s=>`<option>${esc(s.name)}</option>`).join('');if(j.servers?.length)await load()}document.querySelectorAll('.fw-type-btn').forEach(b=>b.onclick=()=>setKind(b.dataset.kind));['portNumber','portProto','serviceName','spIp','spPrefix','spPort','spProto','richRule'].forEach(id=>$(id).addEventListener('input',updatePreview));$('addZone').addEventListener('change',()=>{renderSelectedZone();renderZones();updatePreview()});$('reload').onclick=load;$('server').onchange=load;$('stageRule').onclick=()=>{const {value,error}=buildValue();if(error){$('validation').textContent=error;$('validation').className='small mt-2 text-danger';return}const zone=$('addZone').value;if(stagedAlready(zone,KIND,value)){msg('Diese Regel steht bereits auf der Vormerkliste.','warning');return}STAGE.push({action:'add',kind:KIND,zone,value});renderStage();msg('Regel vorgemerkt. Weitere hinzufuegen oder "Alle anwenden" druecken.','info')};
$('stageApply').onclick=applyStage;$('stageClear').onclick=()=>{STAGE=[];renderStage();msg('Vormerkliste geleert.','info')};
$('createZone').onclick=()=>{const z=$('newZone').value.trim();if(!/^[A-Za-z0-9_-]{1,17}$/.test(z)){msg('Ungueltiger Zonenname. Erlaubt sind bis zu 17 Zeichen aus A-Z, a-z, 0-9 sowie - und _.','danger');return}$('newZone').value='';zoneAdmin('create',z)};
$('filterConfigured').onclick=()=>setZoneFilter('configured');$('filterAll').onclick=()=>setZoneFilter('all');
$('zoneNicAdd').onclick=()=>assignNicToZone($('addZone').value);
$('zoneSourceAdd').onclick=()=>{const ip=$('zoneSourceIp').value.trim(),pre=$('zoneSourcePrefix').value.trim(),v4=isIPv4(ip),v6=isIPv6(ip);if(!v4&&!v6){msg('Bitte eine gültige IPv4- oder IPv6-Adresse eingeben.','danger');return}const max=v4?32:128,p=pre===''?max:+pre;if(!Number.isInteger(p)||p<0||p>max){msg('Ungültiges Präfix.','danger');return}change('add','source',$('addZone').value,ip+'/'+p).then(()=>{$('zoneSourceIp').value='';$('zoneSourcePrefix').value=''})};
$('svcStart').onclick=()=>svc('enable');$('svcRestart').onclick=()=>svc('restart');$('svcStop').onclick=()=>svc('disable');$('addRule').onclick=()=>{const {value,error}=buildValue();if(error){$('validation').textContent=error;$('validation').className='small mt-2 text-danger';return}change('add',KIND,$('addZone').value,value)};$('install').onclick=async()=>{busy('firewalld wird installiert …');try{await api('firewall.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,action:'install',server_name:$('server').value})});msg('firewalld installiert.','success');await load('Firewall-Status wird aktualisiert …')}catch(e){msg(e.message,'danger');idle()}};setKind('port');init();
</script></body></html>